function onAction(e){
  const action=e.currentTarget?.dataset?.action;
  if(action==='course-draft-review'||action==='course-draft-save'){
    if(!copilotWorkflow?.data){toast('The course draft is no longer available.');return;}
    copilotCourseDraft={...copilotWorkflow.data};copilotWorkflow=null;go('Create Course');
    if(action==='course-draft-save')setTimeout(()=>collectCourseForm('Draft'),0);
    else appendCopilotMessage('bot','Review the details in the course builder. Choose Save as draft to keep it private, or Review & publish to confirm publication.');
    return;
  }
  if(action==='course-draft-cancel'){copilotWorkflow=null;copilotCourseDraft=null;appendCopilotMessage('bot','No course was created.');return;}
  if(action==='save-course-draft'){collectCourseForm('Draft');return;}
  if(action==='confirm-course-publish'){collectCourseForm('Published');return;}
  if(action==='create-account'){go('Registration');return;}
  if(action==='enroll'){
    const course=(state.courses||[]).find(item=>item.title===e.currentTarget.dataset.course);if(!course){toast('Course not found.');return;}if(state.enrollments?.some(item=>item.title===course.title)){go('My Learning');return;}
    api('/api/enrollments',{method:'POST',body:JSON.stringify({courseId:String(course.id||course.title)})}).then(async()=>{const result=await api('/api/enrollments');state.enrollments=result.enrollments||[];state.enrolled=state.enrollments.map(item=>item.title);state.courseProgress=Object.fromEntries(state.enrollments.map(item=>[item.title,item.progress]));state.selectedCourse=null;saveState();toast('Enrollment saved to your account.');go('My Learning');}).catch(error=>toast(error.message));return;
  }
  if(action==='start-module'){
    const enrollment=(state.enrollments||[]).find(item=>item.courseId===e.currentTarget.dataset.courseId)||state.enrollments?.[0];if(!enrollment){toast('Enroll in a course before completing a module.');return;}
    api('/api/enrollments/modules/complete',{method:'POST',body:JSON.stringify({courseId:enrollment.courseId,moduleIndex:Number(e.currentTarget.dataset.step)})}).then(async result=>{const current=state.enrollments.find(item=>item.courseId===result.courseId);if(current)Object.assign(current,result);state.courseProgress={...(state.courseProgress||{}),[current?.title||enrollment.title]:result.progress};state.completedModules=(state.completedModules||0)+1;saveState();render();toast(result.status==='completed'?'Course complete. Assessment unlocked.':'Module completion saved.');}).catch(error=>toast(error.message));return;
  }
  if(action==='next-question'){
    if(assessmentIndex<2){assessmentIndex++;selectedAnswer=-1;render();return;}
    const enrollment=(state.enrollments||[]).find(item=>item.status==='completed');if(!enrollment){toast('Complete a course before taking its assessment.');return;}
    const answers=Array.from({length:3},(_,index)=>Number.isInteger(assessmentAnswers[index])&&assessmentAnswers[index]>=0?assessmentAnswers[index]:null);
    api('/api/assessments/attempt',{method:'POST',body:JSON.stringify({courseId:enrollment.courseId,answers})}).then(async result=>{const attempt=result.attempt;state.assessmentDone=true;state.assessmentCorrect=attempt.correct;state.assessmentIncorrect=attempt.incorrect;state.assessmentSkipped=attempt.skipped;state.assessmentScore=attempt.score;state.latestCertificate=attempt.certificate;state.assessmentAttempts=[attempt,...(state.assessmentAttempts||[])];const saved=await api('/api/workspace-state');state.competencies=saved.personal?.competencies||{};state.events=saved.personal?.events||[];state.certificates=saved.personal?.certificates||[];assessmentIndex=0;selectedAnswer=-1;assessmentAnswers=[];go('Assessment Result');}).catch(error=>toast(error.message));return;
  }
  if(action==='learning-preferences'){
    const form=$('#learning-onboarding-form');if(!form)return;const data=new FormData(form),split=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
    api('/api/profile',{method:'PATCH',body:JSON.stringify({currentRole:data.get('targetRole'),experience:data.get('experienceLevel'),interests:split(data.get('interests')),learningGoals:data.get('learningGoals'),preferredTopics:split(data.get('preferredTopics'))})}).then(result=>{state.profile={...state.profile,...result.user.profile,name:result.user.name,email:result.user.email};saveState();render();toast('Learning preferences saved.');}).catch(error=>toast(error.message));return;
  }
  if(action==='course-feedback'){const course=e.currentTarget.dataset.course;state.selectedCourse=course;courseTab='Overview';go('Courses');return;}
if(action==='submit-mission'){const response=String($('#mission-response')?.value||'').trim();api('/api/missions/attempt',{method:'POST',body:JSON.stringify({missionId:'operational-decision-making',response})}).then(async result=>{const attempt=result.attempt;state.missionComplete=true;state.missionScore=attempt.score;state.missionResponse=attempt.response;state.missionRubric=attempt.rubric;const saved=await api('/api/workspace-state');state.competencies=saved.personal?.competencies||{};state.events=saved.personal?.events||[];saveState();go('Mission Result');}).catch(error=>toast(error.message));return;}
if(action==='review-proof'){const id=e.currentTarget.dataset.proofId,status=e.currentTarget.dataset.status;api(`/api/skill-proofs/${id}/review`,{method:'PATCH',body:JSON.stringify({status})}).then(async()=>{state.skillProofs=(await api('/api/skill-proofs')).proofs||[];render();toast(`Evidence ${status.toLowerCase()}.`);}).catch(error=>toast(error.message));return;}
if(action==='change-user-role'){const id=e.currentTarget.dataset.userId,role=$(`[data-user-role-select="${id}"]`)?.value;if(!role)return;api(`/api/users/${id}/role`,{method:'PATCH',body:JSON.stringify({role})}).then(async()=>{state.users=(await api('/api/users')).users||[];render();toast('Role updated. Trainer access requires approval.');}).catch(error=>toast(error.message));return;}
return onActionLegacy(e);
}
document.addEventListener('submit',async event=>{
  if(event.target?.id==='registration-form'){
    event.preventDefault();const form=event.target,data=new FormData(form),password=String(data.get('password')||''),confirmPassword=String(data.get('confirmPassword')||'');
    if(password!==confirmPassword){toast('Passwords do not match.');return;}
    const role=state.pendingRole||'Trainee';
    const payload={name:data.get('fullName'),email:data.get('email'),employeeId:String(data.get('employeeId')||'').trim(),password,role};
    try{const result=await api('/api/auth/register',{method:'POST',body:JSON.stringify(payload)});toast(result.message||'Account created.');go(role==='Admin'?'Admin Login':'Login / Sign Up');}catch(error){toast(error.message);}return;
  }
  if(event.target?.id==='resource-form'){event.preventDefault();const form=event.target,data=new FormData(form),file=data.get('file');if(!file||!file.size){toast('Choose a resource file.');return;}if(file.size>700*1024){toast('Resource files must be 700 KB or smaller.');return;}try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=32768)binary+=String.fromCharCode(...bytes.subarray(offset,offset+32768));const result=await api('/api/resources',{method:'POST',body:JSON.stringify({courseId:data.get('courseId'),title:data.get('title'),description:data.get('description'),filename:file.name,mimeType:file.type,contentBase64:btoa(binary)})});state.resources=[result.resource,...(state.resources||[])];render();toast('Resource uploaded to the course.');}catch(error){toast(error.message);}return;}
  if(event.target?.id==='proof-submission-form'){event.preventDefault();const data=new FormData(event.target);try{const result=await api('/api/skill-proofs',{method:'POST',body:JSON.stringify({courseId:data.get('courseId'),skill:data.get('skill'),title:data.get('title'),details:data.get('details')})});state.proofs=[result.proof,...(state.proofs||[])];saveState();render();toast('Skill evidence sent to the course trainer.');}catch(error){toast(error.message);}return;}
  if(event.target?.id==='learning-onboarding-form'){
    event.preventDefault();const form=event.target,data=new FormData(form),split=value=>String(value||'').split(',').map(item=>item.trim()).filter(Boolean);
    try{const result=await api('/api/profile',{method:'PATCH',body:JSON.stringify({currentRole:data.get('targetRole'),experience:data.get('experienceLevel'),interests:split(data.get('interests')),learningGoals:data.get('learningGoals'),preferredTopics:split(data.get('preferredTopics'))})});state.profile={...state.profile,...result.user.profile,name:result.user.name,email:result.user.email};saveState();render();toast('Learning preferences saved.');}catch(error){toast(error.message);}return;
  }
});moduleList = function moduleList(course){
  const enrollment=(state.enrollments||[]).find(item=>item.title===course.title);
  const skills=Array.isArray(course.skills)?course.skills:[];
  return `<h3>Course modules</h3>${skills.map((skill,index)=>{const complete=index<(enrollment?.completedModules||0);return `<div class="module-row"><span class="module-number">${String(index+1).padStart(2,'0')}</span><span><b>${esc(skill)}</b><small>${complete?'Completed and saved':enrollment&&index===enrollment.completedModules?'Ready to complete':'Enroll and complete the previous module first'}</small></span>${enrollment&&index===enrollment.completedModules?`<button class="link-button" data-action="start-module" data-course-id="${esc(enrollment.courseId)}" data-step="${index}">Complete ‚Üí</button>`:''}</div>`;}).join('')||'<p class="muted">This course has no learning modules configured yet.</p>'}`;
}
learningPage = function learningPage(){
  const enrollments=state.enrollments||[];
  if(!enrollments.length)return `${pageHead('YOUR LEARNING','My Learning','Your personal learning starts when you choose a course.',`<button class="btn btn-primary" data-go="Courses">Explore courses ‚Üí</button>`)}<section class="panel empty-state"><h3>No enrolled courses yet</h3><p>Choose a course from the catalogue. It will appear here after you enroll.</p><button class="btn btn-primary" data-go="Courses">Explore courses</button></section>`;
  return `${pageHead('YOUR LEARNING','My Learning','Course progress is calculated from completed modules.',`<button class="btn btn-quiet" data-go="Courses">Explore more courses</button>`)}${enrollments.map(enrollment=>{const course=(state.courses||[]).find(item=>String(item.id||item.title)===enrollment.courseId||item.title===enrollment.title);return `<section class="panel enrolled-courses"><div class="panel-heading"><div><span class="eyebrow">${esc(enrollment.status)}</span><h3>${esc(enrollment.title)}</h3></div><span class="pill">${enrollment.progress}%</span></div><p>${enrollment.completedModules} of ${enrollment.requiredModules} modules complete</p>${progress(enrollment.progress)}<div class="learning-steps">${(course?.skills||[]).map((skill,index)=>{const done=index<enrollment.completedModules;return `<div class="learning-step ${done?'done':index===enrollment.completedModules?'current':'locked'}"><span>${done?'‚úì':String(index+1).padStart(2,'0')}</span><div><b>${esc(skill)}</b><p>${done?'Completed and saved':index===enrollment.completedModules?'Ready to complete':'Complete the previous module first'}</p></div>${index===enrollment.completedModules?`<button class="link-button" data-action="start-module" data-course-id="${esc(enrollment.courseId)}" data-step="${index}">Complete module ‚Üí</button>`:''}</div>`;}).join('')}</div>${enrollment.status==='completed'?`<button class="btn btn-primary" data-go="Assessments">Start course assessment ‚Üí</button><button class="btn btn-quiet" data-action="course-feedback" data-course="${esc(enrollment.title)}">Rate course</button>`:''}</section>`;}).join('')}`;
}
myLearningPage = learningPage;
learningPath = function learningPath(){
  const enrollments=state.enrollments||[],unfinished=enrollments.find(item=>item.status!=='completed'),interests=state.profile?.interests||[],catalog=(state.courses||[]).filter(course=>!enrollments.some(item=>item.title===course.title));
  const recommended=catalog.find(course=>interests.some(skill=>`${course.title} ${course.subject} ${(course.skills||[]).join(' ')}`.toLowerCase().includes(skill.toLowerCase())))||catalog[0];
  return `${pageHead('YOUR PERSONALIZED ROUTE','Learning path','Recommendations follow the goals you set and your saved course activity.',`<button class="btn btn-quiet" data-action="open-copilot">${icon('spark')} Ask Co-pilot</button>`)}${unfinished?`<section class="panel"><span class="eyebrow">NEXT MODULE</span><h2>${esc(unfinished.title)}</h2><p>${unfinished.completedModules} of ${unfinished.requiredModules} modules complete ¬∑ ${unfinished.progress}%</p>${progress(unfinished.progress)}<button class="btn btn-primary" data-go="My Learning">Continue this course ‚Üí</button></section>`:''}${recommended?`<section class="panel"><span class="eyebrow">CATALOGUE SUGGESTION</span><h2>${esc(recommended.title)}</h2><p>${esc(recommended.description||'Choose a course that fits your goals.')}</p><button class="btn btn-primary" data-action="course-detail" data-course="${esc(recommended.title)}">View course</button></section>`:''}${!unfinished&&!recommended?'<section class="panel empty-state"><h3>Your path is up to date</h3><p>Explore the catalogue to choose another course or update your learning preferences.</p></section>':''}`;
}
gapsPage = function gapsPage(){
  const evidence=state.competencies||{},goal=String(state.profile?.currentRole||'').trim();
  if(!goal)return `${pageHead('YOUR NEXT OPPORTUNITIES','Competency gaps','Set a target role to compare your recorded skills with the platform‚Äôs starter role requirements.',`<button class="btn btn-primary" data-go="Profile & Settings">Set target role ‚Üí</button>`)}<section class="panel empty-state"><h3>No target role selected</h3><p>Your scores come from completed course assessments, missions, and trainer-validated evidence.</p></section>`;
  const role=goal.toLowerCase();
  const requirements=role.includes('data')||role.includes('analyst')?[['Data Analysis',75],['Decision Making',70]]:role.includes('climate')?[['Risk Awareness',75],['Decision Making',70]]:role.includes('forecast')||role.includes('meteorolog')||role.includes('radar')?[['Radar Interpretation',75],['Forecasting',75],['Decision Making',70]]:[...new Set([...Object.keys(evidence),'Decision Making'])].map(skill=>[skill,70]);
  const rows=requirements.map(([skill,target])=>{const current=Number(evidence[skill]||0),gap=Math.max(0,target-current),recommended=(state.courses||[]).find(course=>`${course.title} ${course.subject} ${(course.skills||[]).join(' ')}`.toLowerCase().includes(skill.toLowerCase().split(' ')[0]));return {skill,target,current,gap,recommended};});
  return `${pageHead('YOUR NEXT OPPORTUNITIES','Competency gaps',`Evidence compared with starter competency targets for ${esc(goal)}. Scores update from your account‚Äôs assessment results, missions, and validated proofs.`)}<section class="panel"><h3>Role targets ¬∑ ${esc(goal)}</h3>${rows.map(item=>`<article class="gap-row"><div class="panel-heading"><b>${esc(item.skill)}</b><span class="pill">Target ${item.target}% ¬∑ You ${item.current}%</span></div>${progress(item.current)}<p>${item.gap?`${item.gap} points to target`:'Target met'}${item.recommended?` ¬∑ Suggested course: ${esc(item.recommended.title)}`:''}</p>${item.gap&&item.recommended?`<button class="btn btn-quiet" data-action="course-detail" data-course="${esc(item.recommended.title)}">View suggested course</button>`:''}</article>`).join('')}</section>`;
}
