resourceList = function resourceList(){
  const selected=(state.courses||[]).find(course=>course.title===state.selectedCourse),visible=(state.resources||[]).filter(item=>!selected||String(item.courseId)===String(selected.id||selected.title));
  return `<h3>Learning resources</h3>${visible.length?visible.map(item=>`<div class="resource-row"><span class="resource-icon">‚ñ§</span><span><b>${esc(item.title)}</b><small>${esc(item.filename||item.type||'Resource')} ¬∑ ${esc(item.description||'')}</small></span><a class="link-button" href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Download ‚Üó</a></div>`).join(''):'<div class="empty-state"><h3>No resources available</h3><p>Your trainer will add materials to this course.</p></div>'}`;
}
libraryPage = function libraryPage(){
  const mine=(state.courses||[]).filter(course=>course.trainerId===currentUser?.id||course.ownerId===currentUser?.id),options=mine.map(course=>`<option value="${esc(course.id||course.title)}">${esc(course.title)}</option>`).join(''),resources=(state.resources||[]).filter(item=>item.trainerId===currentUser?.id||state.role==='Admin');
  return `${pageHead('TRAINER LIBRARY','Learning resources','Upload a course resource for enrolled learners.')}${mine.length?`<form id="resource-form" class="panel form-panel"><label class="field"><span>Course</span><select name="courseId" required>${options}</select></label><label class="field"><span>Resource title</span><input name="title" required maxlength="160"/></label><label class="field"><span>Description</span><textarea name="description" maxlength="1000"></textarea></label><label class="field"><span>PDF, text, PNG, or JPEG (700 KB max)</span><input name="file" type="file" accept="application/pdf,text/plain,image/png,image/jpeg" required/></label><button class="btn btn-primary">Upload resource</button></form>`:'<section class="panel empty-state"><h3>Create a course first</h3><p>Resources are attached to courses owned by your trainer account.</p><button class="btn btn-primary" data-go="Create Course">Create course</button></section>'}<section class="panel library-list"><h3>My course resources</h3>${resources.length?resources.map(item=>`<div class="resource-row"><b>${esc(item.title)}</b><small>${esc(item.filename||item.type||'')}</small><a href="${esc(item.url)}" target="_blank" rel="noopener noreferrer">Download</a></div>`).join(''):'<p>No resources uploaded yet.</p>'}</section>`;
}

render();
